function noise(ctx,seconds){const length=Math.max(1,Math.floor(ctx.sampleRate*seconds)),buffer=ctx.createBuffer(1,length,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=Math.random()*2-1;const src=ctx.createBufferSource();src.buffer=buffer;return src;}
function envelope(ctx,out,t,attack,peak,decay){const g=ctx.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,peak),t+Math.max(.002,attack));g.gain.exponentialRampToValueAtTime(0.0001,t+Math.max(.002,attack)+Math.max(.01,decay));g.connect(out);return g;}
function tone(ctx,out,t,{type='sine',from=440,to=from,attack=.01,peak=.5,decay=.3,filter=0,filterTo=0,q=1}){const o=ctx.createOscillator();o.type=type;o.frequency.setValueAtTime(Math.max(20,from),t);if(to!==from)o.frequency.exponentialRampToValueAtTime(Math.max(20,to),t+attack+decay);const g=envelope(ctx,out,t,attack,peak,decay);if(filter){const f=ctx.createBiquadFilter();f.type='lowpass';f.Q.value=q;f.frequency.setValueAtTime(filter,t);if(filterTo)f.frequency.exponentialRampToValueAtTime(Math.max(40,filterTo),t+attack+decay);o.connect(f);f.connect(g);}else o.connect(g);o.start(t);o.stop(t+attack+decay+.06);}
function hiss(ctx,out,t,{seconds=.4,type='bandpass',from=400,to=3000,q=1.2,attack=.05,peak=.5}){const src=noise(ctx,seconds+.1),f=ctx.createBiquadFilter();f.type=type;f.Q.value=q;f.frequency.setValueAtTime(Math.max(40,from),t);f.frequency.exponentialRampToValueAtTime(Math.max(40,to),t+seconds);src.connect(f);f.connect(envelope(ctx,out,t,attack,peak,Math.max(.05,seconds-attack)));src.start(t);src.stop(t+seconds+.1);}
function chord(ctx,out,t,notes,{type='triangle',attack=.015,peak=.14,decay=.45,filter=3200}){for(const n of notes)tone(ctx,out,t,{type,from:NOTE(n),attack,peak,decay,filter});}
const NOTE=n=>440*2**((n-69)/12);
export const SYNTH={
 whoosh:(ctx,out,t)=>{hiss(ctx,out,t,{seconds:.48,from:220,to:4200,q:1.5,attack:.14,peak:.68});tone(ctx,out,t,{type:'sine',from:240,to:90,attack:.08,peak:.22,decay:.35});},
 riser:(ctx,out,t)=>{tone(ctx,out,t,{type:'sawtooth',from:130,to:1100,attack:.38,peak:.14,decay:.18,filter:800,filterTo:4200});tone(ctx,out,t,{type:'triangle',from:260,to:1650,attack:.36,peak:.12,decay:.18});hiss(ctx,out,t,{seconds:.52,type:'highpass',from:700,to:6500,attack:.4,peak:.24});},
 impact:(ctx,out,t)=>{tone(ctx,out,t,{type:'sine',from:140,to:34,attack:.004,peak:1.0,decay:.68});tone(ctx,out,t,{type:'triangle',from:280,to:65,attack:.003,peak:.5,decay:.25});hiss(ctx,out,t,{seconds:.42,type:'lowpass',from:3600,to:140,q:.8,attack:.003,peak:.85});chord(ctx,out,t,[69,76,81],{type:'triangle',attack:.005,peak:.16,decay:.55,filter:3800});},
 zap:(ctx,out,t)=>{for(let i=0;i<6;i++)tone(ctx,out,t+i*.032,{type:'sawtooth',from:1100+Math.random()*1900,to:160,attack:.002,peak:.14,decay:.08,filter:4800,filterTo:900});hiss(ctx,out,t,{seconds:.34,type:'bandpass',from:3200,to:6800,q:1.6,attack:.004,peak:.38});},
 thud:(ctx,out,t)=>{tone(ctx,out,t,{type:'sine',from:88,to:28,attack:.012,peak:.85,decay:.95});hiss(ctx,out,t,{seconds:.75,type:'lowpass',from:520,to:75,attack:.02,peak:.38});},
 drumroll:(ctx,out,t)=>{for(let i=0;i<24;i++){const at=t+i*.065;hiss(ctx,out,at,{seconds:.055,type:'bandpass',from:1600,to:750,q:.9,attack:.003,peak:.1+i*.012});tone(ctx,out,at,{type:'triangle',from:140+i*2,to:90,attack:.002,peak:.08+i*.004,decay:.05});}tone(ctx,out,t+1.6,{type:'sine',from:115,to:42,attack:.005,peak:.75,decay:.4});},
 fanfare:(ctx,out,t)=>{const lead=[[67,0,.13],[72,.14,.13],[76,.28,.13],[79,.42,.3],[76,.74,.12],[79,.88,1.25]];for(const [n,at,len] of lead){tone(ctx,out,t+at,{type:'sawtooth',from:NOTE(n),attack:.02,peak:.17,decay:len,filter:2800,filterTo:1400});tone(ctx,out,t+at,{type:'triangle',from:NOTE(n)*1.004,attack:.02,peak:.15,decay:len});}chord(ctx,out,t+.88,[48,60,64,67,72],{type:'triangle',attack:.03,peak:.14,decay:1.4,filter:3200});tone(ctx,out,t+.88,{type:'sine',from:72,to:38,attack:.005,peak:.68,decay:.55});hiss(ctx,out,t+.88,{seconds:1.1,type:'highpass',from:5500,to:9000,attack:.005,peak:.14});},
 sparkle:(ctx,out,t)=>{const scale=[84,86,88,91,93,96,98];for(let i=0;i<14;i++)tone(ctx,out,t+i*.07+Math.random()*.025,{type:'sine',from:NOTE(scale[(i*3)%scale.length]),attack:.005,peak:.09,decay:.28});},
 pop:(ctx,out,t)=>{tone(ctx,out,t,{type:'triangle',from:720,to:1180,attack:.003,peak:.25,decay:.09});tone(ctx,out,t+.05,{type:'sine',from:1320,to:1760,attack:.004,peak:.22,decay:.16});hiss(ctx,out,t,{seconds:.14,type:'bandpass',from:2400,to:4800,attack:.004,peak:.22});},
 clutch:(ctx,out,t)=>{for(let i=0;i<3;i++){const at=t+i*.44;tone(ctx,out,at,{type:'triangle',from:NOTE(74),attack:.006,peak:.18,decay:.12});tone(ctx,out,at+.12,{type:'triangle',from:NOTE(69),attack:.006,peak:.15,decay:.12});tone(ctx,out,at,{type:'sine',from:78,to:40,attack:.005,peak:.48,decay:.2});}},
 mega:(ctx,out,t)=>{for(let i=0;i<6;i++)tone(ctx,out,t+i*.065,{type:'triangle',from:NOTE(64+i*3),attack:.012,peak:.18,decay:.4});chord(ctx,out,t+.44,[64,71,76,83,88],{type:'triangle',attack:.015,peak:.15,decay:.85,filter:4200});hiss(ctx,out,t+.42,{seconds:.5,type:'bandpass',from:1200,to:5200,attack:.01,peak:.4});},
 charge_pulse:(ctx,out,t)=>{tone(ctx,out,t,{type:'sine',from:180,to:520,attack:.08,peak:.2,decay:.28});hiss(ctx,out,t,{seconds:.3,type:'bandpass',from:600,to:2400,attack:.08,peak:.18});},
 sub_thump:(ctx,out,t)=>{tone(ctx,out,t,{type:'sine',from:118,to:34,attack:.003,peak:.78,decay:.32});hiss(ctx,out,t,{seconds:.16,type:'lowpass',from:1400,to:180,attack:.003,peak:.35});},
 el_electric:(ctx,out,t)=>{for(let i=0;i<4;i++)tone(ctx,out,t+i*.022,{type:'sawtooth',from:1400+i*420,to:320,attack:.002,peak:.11,decay:.06,filter:4600});hiss(ctx,out,t,{seconds:.16,type:'highpass',from:3200,to:7200,attack:.003,peak:.22});},
 el_fire:(ctx,out,t)=>{hiss(ctx,out,t,{seconds:.34,type:'lowpass',from:2400,to:280,q:.8,attack:.02,peak:.38});tone(ctx,out,t,{type:'triangle',from:160,to:58,attack:.01,peak:.3,decay:.26});},
 el_ice:(ctx,out,t)=>{chord(ctx,out,t,[86,91,98,103],{type:'sine',attack:.003,peak:.11,decay:.28});hiss(ctx,out,t,{seconds:.22,type:'highpass',from:4200,to:8000,attack:.004,peak:.22});},
 el_water:(ctx,out,t)=>{tone(ctx,out,t,{type:'sine',from:280,to:760,attack:.015,peak:.24,decay:.16});tone(ctx,out,t+.06,{type:'sine',from:520,to:240,attack:.01,peak:.18,decay:.18});hiss(ctx,out,t,{seconds:.28,type:'bandpass',from:700,to:2600,q:1.4,attack:.015,peak:.28});},
 el_steel:(ctx,out,t)=>{for(const f of [680,1040,1590,2310])tone(ctx,out,t,{type:'triangle',from:f,to:f*.98,attack:.003,peak:.12,decay:.38});},
 el_arcane:(ctx,out,t)=>{chord(ctx,out,t,[72,79,83,86],{type:'sine',attack:.02,peak:.12,decay:.45});},
 cd_tick:(ctx,out,t)=>{tone(ctx,out,t,{type:'triangle',from:NOTE(72),attack:.004,peak:.22,decay:.15});},
 cd_go:(ctx,out,t)=>{chord(ctx,out,t,[72,76,79,84],{type:'triangle',attack:.008,peak:.16,decay:.48});},
 defeat:(ctx,out,t)=>{tone(ctx,out,t,{type:'triangle',from:660,to:190,attack:.01,peak:.32,decay:.55});chord(ctx,out,t+.08,[67,63,60],{type:'sine',attack:.02,peak:.15,decay:.65});hiss(ctx,out,t,{seconds:.45,type:'bandpass',from:2400,to:380,q:1.1,attack:.02,peak:.24});},
 win_chime:(ctx,out,t)=>{const notes=[72,76,79,84];notes.forEach((n,i)=>tone(ctx,out,t+i*.07,{type:'triangle',from:NOTE(n),attack:.005,peak:.2,decay:.35}));chord(ctx,out,t+.28,[72,76,79,84],{type:'sine',attack:.01,peak:.16,decay:.75});}
};
export class BattleAudio{
 constructor(report=()=>{}){this.report=report;this.enabled=false;this.musicEnabled=true;this.musicVolume=.065;this.effectsVolume=.85;this.music=new Audio('assets/audio/battle.mp3?v=6');this.music.preload='auto';this.music.loop=true;this.music.volume=this.musicVolume;this.cries=new Map();this.active=new Set();this.pools=new Map();this.music.onerror=()=>this.report('Battle music could not load. Tap Sound to retry.');for(const name of ['dash','charge','whoosh','strike','heavy','flame','water','electric','ice','energy','ground','steel','slash','bite','victory','punch','kick','beam','thunder','crack','debris','collapse','ready'])this.pools.set(name,Array.from({length:3},()=>{const a=new Audio(`assets/sfx/${name}.wav`);a.preload='auto';return a}));}
 async enable(){this.enabled=true;this.blocked=false;}
 async begin(enabled){this.battling=true;if(!enabled){this.disable();return}try{this.enabled=true;this.blocked=false;if(this.musicEnabled)await this.music.play();}catch{this.blocked=true;this.report('Audio playback blocked — tap Sound to retry.');}}
 cancelSpeech(){if(typeof window!=='undefined')window.speechSynthesis?.cancel?.();}
 disable(){this.cancelSpeech();this.enabled=false;this.music.pause();for(const a of this.active)a.pause();this.active.clear();clearTimeout(this.duckTimer);this.music.volume=this.musicVolume;}
 background(on){this.battling=on;if(on&&this.enabled&&this.musicEnabled)this.music.play().catch(()=>{this.blocked=true;this.report('Music playback blocked — tap Sound to retry.')});else this.music.pause();}
 setMix(kind,value){const v=Math.max(0,Math.min(1,value));if(kind==='music'){this.musicVolume=v;this.music.volume=this.ducked?v*.22:v}else this.effectsVolume=v;}
 duck(duration){this.ducked=true;this.music.volume=this.musicVolume*(this.musicVolume<=.1?.22:.68);clearTimeout(this.duckTimer);this.duckTimer=setTimeout(()=>{this.ducked=false;this.music.volume=this.musicVolume},this.musicVolume<=.1?duration:Math.min(duration,420));this.duckTimer?.unref?.();}
 routeRecording(a){if(!this.recordContext||!this.recordNodes||!this.recordDestination||this.recordNodes.has(a))return;try{const source=this.recordContext.createMediaElementSource(a);source.connect(this.recordContext.destination);source.connect(this.recordDestination);this.recordNodes.set(a,source);}catch{}}
 getRecordingStream(){try{if(typeof window==='undefined')return null;const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return null;if(!this.recordContext){this.recordContext=new Context();this.recordDestination=this.recordContext.createMediaStreamDestination();this.recordNodes=new WeakMap();}this.recordContext.resume?.().catch(()=>{});for(const a of [this.music,...[...this.pools.values()].flat(),...this.cries.values()])this.routeRecording(a);return this.recordDestination.stream;}catch{return null;}}
 play(a,volume){this.routeRecording(a);a.volume=Math.max(0,Math.min(1,volume));a.currentTime=0;this.active.add(a);a.onended=()=>this.active.delete(a);a.play().catch(()=>{this.active.delete(a);this.report('An attack sound could not play — tap Test hit to retry.');});}
 cry(id,bundled){if(!this.enabled)return;let a=this.cries.get(id);if(!a){a=new Audio();a.crossOrigin='anonymous';a.src=bundled?`assets/audio/${id}.mp3`:`https://raw.githubusercontent.com/PokeAPI/cries/main/cries/pokemon/latest/${id}.ogg`;this.cries.set(id,a)}this.duck(700);this.play(a,this.effectsVolume*.45);}
 pause(on){if(typeof window!=='undefined'){if(on)window.speechSynthesis?.pause?.();else window.speechSynthesis?.resume?.();}if(on){this.music.pause();for(const a of this.active)a.pause()}else if(this.enabled){this.background(this.battling);for(const a of this.active)a.play().catch(()=>this.active.delete(a))}}

 hush(){for(const a of this.active)a.pause();this.active.clear();this.music.pause();clearTimeout(this.duckTimer);this.ducked=false;this.music.volume=this.musicVolume;}
 quiet(duration=180){for(const a of this.active)if(a._cue==='charge'||a._cue==='cry'){a.pause();this.active.delete(a)}this.duck(duration);this.music.volume=this.musicVolume*.35;}
 cue(name,gain=1){if(!this.enabled)return;const pool=this.pools.get(name);if(!pool)return;const a=pool.find(x=>!this.active.has(x))||pool[0];a._cue=name;this.play(a,this.effectsVolume*gain);}
 sfx(type,phase='attack',strength=false,move){if(!this.enabled)return;const heavy=typeof strength==='number'?strength>=.75:strength;const pack={fire:'flame',water:'water',electric:'electric',ice:'ice',ground:'ground',rock:'ground',steel:'steel',fighting:'whoosh',normal:'whoosh',flying:'whoosh',grass:'whoosh',bug:'whoosh'};const contact=move?.fx==='slash'?'slash':move?.fx==='bite'||move?.name==='crunch'?'bite':move?.fx==='kick'?'kick':move?.fx==='punch'||move?.name==='close-combat'?'punch':null;const name=['ready','victory','collapse','thunder','beam'].includes(phase)?phase:phase==='impact'&&contact?contact:phase==='impact'?(heavy?'heavy':type==='steel'?'steel':'strike'):phase==='charge'?'charge':phase==='dash'||phase==='miss'?'whoosh':pack[type]||'energy';this.duck(heavy?900:650);this.cue(name,phase==='charge'?.42:1);if(phase==='charge')this.synth('charge_pulse',.45);if(phase==='attack'){const el={electric:'el_electric',fire:'el_fire',ice:'el_ice',water:'el_water',steel:'el_steel',psychic:'el_arcane',fairy:'el_arcane',ghost:'el_arcane',dragon:'el_arcane'}[type];if(el)this.synth(el,.55);}if(phase==='impact'){const el={electric:'el_electric',fire:'el_fire',ice:'el_ice',water:'el_water',steel:'el_steel',psychic:'el_arcane',fairy:'el_arcane',ghost:'el_arcane',dragon:'el_arcane'}[type];if(el)this.synth(el,.5);if(heavy){if(name!=='heavy')this.cue('heavy',.55);this.cue('crack',.42);this.cue('debris',.28);this.synth('sub_thump',.8);}}}
 dash(gain=.7){this.duck(350);this.cue('dash',gain);}
 // Procedural WebAudio stingers with a shared compressor + arena echo bus (recorded into captured videos).
 synthContext(){if(typeof window==='undefined')return null;const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return null;if(!this.recordContext){this.recordContext=new Context();this.recordDestination=this.recordContext.createMediaStreamDestination?.();this.recordNodes=new WeakMap();}this.recordContext.resume?.().catch(()=>{});if(!this.synthBus){try{const comp=this.recordContext.createDynamicsCompressor?.();const target=comp||this.recordContext.destination;if(comp){comp.threshold.value=-14;comp.ratio.value=4;comp.connect(this.recordContext.destination);if(this.recordDestination)comp.connect(this.recordDestination);}const delay=this.recordContext.createDelay?.(.5);const fb=this.recordContext.createGain?.();const wet=this.recordContext.createGain?.();if(delay&&fb&&wet){delay.delayTime.value=.13;fb.gain.value=.22;wet.gain.value=.22;delay.connect(fb);fb.connect(delay);delay.connect(wet);wet.connect(target);}this.synthBus=this.recordContext.createGain();this.synthBus.connect(target);if(delay)this.synthBus.connect(delay);}catch{this.synthBus=null;}}return this.recordContext;}
 synth(name,gain=1,delay=0){if(!this.enabled)return;try{const ctx=this.synthContext();if(!ctx||!SYNTH[name])return;const out=ctx.createGain();out.gain.value=Math.max(0,Math.min(1,this.effectsVolume*gain))*.55;if(this.synthBus)out.connect(this.synthBus);else{out.connect(ctx.destination);if(this.recordDestination)out.connect(this.recordDestination);}SYNTH[name](ctx,out,ctx.currentTime+delay);if(['impact','fanfare','mega'].includes(name))this.duck(1400);}catch{}}
 countdownCue(step){const isGo=String(step).toUpperCase().startsWith('GO');this.cue(isGo?'victory':'ready',isGo?.7:.45);this.synth(isGo?'cd_go':'cd_tick',isGo?.65:.45);}
}
